import { useState, useEffect, useRef, useCallback } from "react";
 
// ---------- MITO brand tokens ----------
const C = {
  teal: "#16495C",      // deep petrol teal (display background)
  teal2: "#1F5F76",     // panel teal
  teal3: "#0E3543",     // darkest
  orange: "#E87722",    // Marubeni-Itochu orange (signature accent)
  orangeSoft: "#F4A45C",
  paper: "#F5F3EE",     // off-white
  steel: "#9FB4BC",     // muted steel grey-blue
};
 
const STORAGE_KEY = "sundowner:tracker:v1";
const POLL_MS = 5000;
 
// ---------- shared data helpers ----------
const emptyData = { target: 10000, donations: [] };
 
async function loadData() {
  try {
    const value = localStorage.getItem(STORAGE_KEY);
    return value ? JSON.parse(value) : null;
  } catch (e) {
    return null;
  }
}

async function saveData(data) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    return true;
  } catch (e) {
    return false;
  }
}
 
// ---------- MITO logo (Marubeni-Itochu Steel mark, white text variant, embedded) ----------
const LOGO_SRC = "data:image/png;base64,";
 
function Logo({ height = 34 }) {
  return (
    <img
      src={LOGO_SRC}
      alt="Marubeni-Itochu Steel"
      style={{ height, width: "auto" }}
    />
  );
}
 
const fmt = (n) =>
  new Intl.NumberFormat("en-AU", {
    style: "currency",
    currency: "AUD",
    maximumFractionDigits: 0,
  }).format(n || 0);
 
const timeAgo = (ts) => {
  const s = Math.floor((Date.now() - ts) / 1000);
  if (s < 60) return "just now";
  const m = Math.floor(s / 60);
  if (m < 60) return `${m} min ago`;
  const h = Math.floor(m / 60);
  return `${h} hr ago`;
};
 
// ---------- animated count-up ----------
function useCountUp(value, duration = 900) {
  const [display, setDisplay] = useState(value);
  const fromRef = useRef(value);
  const raf = useRef(null);
  useEffect(() => {
    const reduced =
      typeof window !== "undefined" &&
      window.matchMedia &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) {
      setDisplay(value);
      fromRef.current = value;
      return;
    }
    const from = fromRef.current;
    const start = performance.now();
    cancelAnimationFrame(raf.current);
    const tick = (now) => {
      const p = Math.min(1, (now - start) / duration);
      const eased = 1 - Math.pow(1 - p, 3);
      setDisplay(Math.round(from + (value - from) * eased));
      if (p < 1) raf.current = requestAnimationFrame(tick);
      else fromRef.current = value;
    };
    raf.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf.current);
  }, [value, duration]);
  return display;
}
 
// ---------- pipe progress bar (signature element) ----------
function PipeGauge({ total, target }) {
  const pct = target > 0 ? Math.min(100, (total / target) * 100) : 0;
  return (
    <div className="w-full">
      <div
        className="relative w-full rounded-full overflow-hidden"
        style={{
          height: 44,
          background:
            "linear-gradient(180deg, #0b2b36 0%, #123c4b 45%, #0b2b36 100%)",
          boxShadow:
            "inset 0 3px 8px rgba(0,0,0,0.55), inset 0 -2px 4px rgba(255,255,255,0.06)",
          border: "1px solid rgba(159,180,188,0.25)",
        }}
        role="progressbar"
        aria-valuenow={Math.round(pct)}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label="Progress toward fundraising target"
      >
        <div
          className="absolute left-0 top-0 h-full transition-all duration-1000 ease-out"
          style={{
            width: `${pct}%`,
            background: `linear-gradient(180deg, ${C.orangeSoft} 0%, ${C.orange} 40%, #b95a12 100%)`,
            boxShadow: "0 0 24px rgba(232,119,34,0.5)",
            borderRadius: "9999px",
          }}
        />
        {/* pipe sheen */}
        <div
          className="absolute inset-0 pointer-events-none"
          style={{
            background:
              "linear-gradient(180deg, rgba(255,255,255,0.22) 0%, rgba(255,255,255,0) 35%)",
            borderRadius: "9999px",
          }}
        />
        {/* weld-seam segment marks every 10% */}
        {Array.from({ length: 9 }).map((_, i) => (
          <div
            key={i}
            className="absolute top-0 h-full"
            style={{
              left: `${(i + 1) * 10}%`,
              width: 1,
              background: "rgba(245,243,238,0.14)",
            }}
          />
        ))}
      </div>
      <div
        className="flex justify-between mt-2 text-sm tracking-widest uppercase"
        style={{ color: C.steel }}
      >
        <span>{Math.round(pct)}% of target</span>
        <span>Target {fmt(target)}</span>
      </div>
    </div>
  );
}
 
// ---------- guest display ----------
function DisplayView({ data, onExit }) {
  const total = data.donations.reduce((s, d) => s + d.amount, 0);
  const shown = useCountUp(total);
  const recent = [...data.donations].sort((a, b) => b.ts - a.ts).slice(0, 6);
  const reached = data.target > 0 && total >= data.target;
 
  return (
    <div
      className="min-h-screen flex flex-col"
      style={{
        background: `radial-gradient(1200px 700px at 70% -10%, ${C.teal2} 0%, ${C.teal} 45%, ${C.teal3} 100%)`,
        color: C.paper,
      }}
    >
      {/* header */}
      <div className="flex items-center justify-between px-8 pt-6">
        <div className="flex items-center gap-4">
          <Logo height={56} />
          <div className="leading-tight" style={{ borderLeft: `1px solid ${C.steel}55`, paddingLeft: 16 }}>
            <div className="font-bold tracking-wide text-lg">MITO Sundowner</div>
            <div
              className="text-xs uppercase tracking-[0.25em]"
              style={{ color: C.steel }}
            >
              Fundraising tracker
            </div>
          </div>
        </div>
        <button
          onClick={onExit}
          className="text-xs uppercase tracking-widest px-3 py-2 rounded opacity-40 hover:opacity-100 transition-opacity"
          style={{ color: C.steel, border: `1px solid ${C.steel}44` }}
        >
          Exit display
        </button>
      </div>
 
      {/* hero total */}
      <div className="flex-1 flex flex-col items-center justify-center px-8 -mt-4">
        <div
          className="uppercase tracking-[0.4em] text-sm md:text-base mb-3"
          style={{ color: C.orangeSoft }}
        >
          {reached ? "Target reached — thank you!" : "Raised so far tonight"}
        </div>
        <div
          className="font-black tabular-nums leading-none text-center"
          style={{
            fontSize: "clamp(4rem, 14vw, 11rem)",
            letterSpacing: "-0.02em",
            textShadow: "0 6px 40px rgba(0,0,0,0.45)",
          }}
        >
          {fmt(shown)}
        </div>
 
        <div className="w-full max-w-3xl mt-10">
          <PipeGauge total={total} target={data.target} />
        </div>
      </div>
 
      {/* recent donations ticker */}
      <div className="px-8 pb-8">
        <div
          className="uppercase tracking-[0.3em] text-xs mb-3"
          style={{ color: C.steel }}
        >
          Recent donations
        </div>
        <div className="flex gap-3 overflow-hidden flex-wrap">
          {recent.length === 0 && (
            <div className="text-sm" style={{ color: C.steel }}>
              Donations will appear here as they come in.
            </div>
          )}
          {recent.map((d, i) => (
            <div
              key={d.id}
              className="px-5 py-3 rounded-lg flex items-baseline gap-3"
              style={{
                background:
                  i === 0 ? "rgba(232,119,34,0.18)" : "rgba(245,243,238,0.07)",
                border: `1px solid ${
                  i === 0 ? "rgba(232,119,34,0.5)" : "rgba(159,180,188,0.2)"
                }`,
              }}
            >
              <span className="font-bold text-xl tabular-nums">
                {fmt(d.amount)}
              </span>
              <span className="text-xs" style={{ color: C.steel }}>
                {timeAgo(d.ts)}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
 
// ---------- events console ----------
function ConsoleView({ data, setData, onExit, syncState }) {
  const [amount, setAmount] = useState("");
  const [targetEdit, setTargetEdit] = useState(String(data.target));
  const [confirmReset, setConfirmReset] = useState(false);
  const total = data.donations.reduce((s, d) => s + d.amount, 0);
  const quick = [20, 50, 100, 250, 500];
 
  const commit = useCallback(
    async (next) => {
      setData(next); // optimistic
      await saveData(next);
    },
    [setData]
  );
 
  const addDonation = async (amt) => {
    const v = Number(amt);
    if (!v || v <= 0) return;
    const next = {
      ...data,
      donations: [
        ...data.donations,
        { id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, amount: v, ts: Date.now() },
      ],
    };
    setAmount("");
    await commit(next);
  };
 
  const removeDonation = async (id) => {
    await commit({ ...data, donations: data.donations.filter((d) => d.id !== id) });
  };
 
  const updateTarget = async () => {
    const v = Number(targetEdit);
    if (!v || v <= 0) return;
    await commit({ ...data, target: v });
  };
 
  const resetAll = async () => {
    setConfirmReset(false);
    await commit({ ...data, donations: [] });
  };
 
  const recent = [...data.donations].sort((a, b) => b.ts - a.ts).slice(0, 10);
 
  return (
    <div className="min-h-screen" style={{ background: C.paper }}>
      <div
        className="px-5 py-4 flex items-center justify-between"
        style={{ background: C.teal, color: C.paper }}
      >
        <div className="flex items-center gap-3">
          <Logo height={40} />
          <div style={{ borderLeft: "1px solid rgba(245,243,238,0.3)", paddingLeft: 12 }}>
            <div className="font-bold">Events console</div>
            <div className="text-xs" style={{ color: C.steel }}>
              Sundowner tracker ·{" "}
              {syncState === "ok" ? "synced" : syncState === "saving" ? "saving…" : "offline — retrying"}
            </div>
          </div>
        </div>
        <button
          onClick={onExit}
          className="text-xs uppercase tracking-widest px-3 py-2 rounded"
          style={{ color: C.paper, border: "1px solid rgba(245,243,238,0.3)" }}
        >
          Switch mode
        </button>
      </div>
 
      <div className="max-w-xl mx-auto p-5 space-y-6">
        {/* running total */}
        <div
          className="rounded-xl p-5 text-center"
          style={{ background: "#fff", border: "1px solid #e2ddd2" }}
        >
          <div className="text-xs uppercase tracking-widest text-stone-500 mb-1">
            Running total
          </div>
          <div
            className="font-black text-5xl tabular-nums"
            style={{ color: C.teal }}
          >
            {fmt(total)}
          </div>
          <div className="text-sm text-stone-500 mt-1">
            of {fmt(data.target)} target · {data.donations.length} donations
          </div>
        </div>
 
        {/* add donation */}
        <div
          className="rounded-xl p-5"
          style={{ background: "#fff", border: "1px solid #e2ddd2" }}
        >
          <div className="font-semibold mb-3" style={{ color: C.teal3 }}>
            Add donation
          </div>
          <div className="flex gap-2 flex-wrap mb-3">
            {quick.map((q) => (
              <button
                key={q}
                onClick={() => addDonation(q)}
                className="px-4 py-3 rounded-lg font-bold text-lg active:scale-95 transition-transform"
                style={{
                  background: "rgba(232,119,34,0.12)",
                  color: "#b95a12",
                  border: "1px solid rgba(232,119,34,0.4)",
                }}
              >
                ${q}
              </button>
            ))}
          </div>
          <div className="flex gap-2">
            <input
              type="number"
              inputMode="decimal"
              min="1"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && addDonation(amount)}
              placeholder="Custom amount"
              className="flex-1 px-4 py-3 rounded-lg text-lg border border-stone-300 focus:outline-none"
              style={{ background: C.paper }}
            />
            <button
              onClick={() => addDonation(amount)}
              className="px-6 py-3 rounded-lg font-bold text-white active:scale-95 transition-transform"
              style={{ background: C.orange }}
            >
              Add
            </button>
          </div>
        </div>
 
        {/* recent entries with remove */}
        <div
          className="rounded-xl p-5"
          style={{ background: "#fff", border: "1px solid #e2ddd2" }}
        >
          <div className="font-semibold mb-3" style={{ color: C.teal3 }}>
            Recent entries
          </div>
          {recent.length === 0 && (
            <div className="text-sm text-stone-500">No donations yet.</div>
          )}
          <div className="space-y-2">
            {recent.map((d) => (
              <div
                key={d.id}
                className="flex items-center justify-between px-3 py-2 rounded-lg"
                style={{ background: C.paper }}
              >
                <span className="font-bold tabular-nums" style={{ color: C.teal }}>
                  {fmt(d.amount)}
                </span>
                <span className="text-xs text-stone-500">{timeAgo(d.ts)}</span>
                <button
                  onClick={() => removeDonation(d.id)}
                  className="text-xs px-3 py-1 rounded border border-stone-300 text-stone-600"
                >
                  Remove
                </button>
              </div>
            ))}
          </div>
        </div>
 
        {/* settings */}
        <div
          className="rounded-xl p-5"
          style={{ background: "#fff", border: "1px solid #e2ddd2" }}
        >
          <div className="font-semibold mb-3" style={{ color: C.teal3 }}>
            Settings
          </div>
          <div className="flex gap-2 mb-4">
            <input
              type="number"
              inputMode="decimal"
              min="1"
              value={targetEdit}
              onChange={(e) => setTargetEdit(e.target.value)}
              className="flex-1 px-4 py-3 rounded-lg border border-stone-300 focus:outline-none"
              style={{ background: C.paper }}
              aria-label="Fundraising target"
            />
            <button
              onClick={updateTarget}
              className="px-5 py-3 rounded-lg font-semibold text-white"
              style={{ background: C.teal }}
            >
              Set target
            </button>
          </div>
          {!confirmReset ? (
            <button
              onClick={() => setConfirmReset(true)}
              className="text-sm text-red-700 underline"
            >
              Reset all donations
            </button>
          ) : (
            <div className="flex items-center gap-3">
              <span className="text-sm text-red-700 font-semibold">
                Delete all {data.donations.length} donations?
              </span>
              <button
                onClick={resetAll}
                className="px-4 py-2 rounded-lg text-white text-sm font-bold bg-red-700"
              >
                Yes, reset
              </button>
              <button
                onClick={() => setConfirmReset(false)}
                className="px-4 py-2 rounded-lg text-sm border border-stone-300"
              >
                Cancel
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
 
// ---------- mode picker ----------
function Landing({ onPick }) {
  return (
    <div
      className="min-h-screen flex flex-col items-center justify-center px-6"
      style={{
        background: `radial-gradient(900px 600px at 50% -20%, ${C.teal2} 0%, ${C.teal} 50%, ${C.teal3} 100%)`,
        color: C.paper,
      }}
    >
      <div className="mb-6">
        <Logo height={130} />
      </div>
      <h1 className="font-black text-4xl md:text-5xl text-center mb-2">
        MITO Sundowner
      </h1>
      <p
        className="uppercase tracking-[0.35em] text-xs mb-10"
        style={{ color: C.steel }}
      >
        Fundraising tracker
      </p>
      <div className="flex flex-col sm:flex-row gap-4 w-full max-w-lg">
        <button
          onClick={() => onPick("display")}
          className="flex-1 py-6 rounded-xl font-bold text-lg active:scale-95 transition-transform"
          style={{ background: C.orange, color: "#fff" }}
        >
          Guest display
          <div className="text-xs font-normal opacity-80 mt-1">
            Full-screen live total for the venue screen
          </div>
        </button>
        <button
          onClick={() => onPick("console")}
          className="flex-1 py-6 rounded-xl font-bold text-lg active:scale-95 transition-transform"
          style={{
            background: "rgba(245,243,238,0.08)",
            border: `1px solid ${C.steel}55`,
            color: C.paper,
          }}
        >
          Events console
          <div className="text-xs font-normal mt-1" style={{ color: C.steel }}>
            Enter donations behind the scenes
          </div>
        </button>
      </div>
      <p className="text-xs mt-10 text-center max-w-md" style={{ color: C.steel }}>
        Open this app on both devices and pick a mode on each. Updates appear on
        the display within a few seconds.
      </p>
    </div>
  );
}
 
// ---------- root ----------
export default function App() {
  const [mode, setMode] = useState(null);
  const [data, setDataState] = useState(emptyData);
  const [syncState, setSyncState] = useState("ok");
  const dataRef = useRef(data);
  dataRef.current = data;
 
  const setData = (next) => setDataState(next);
 
  // initial load + polling
  useEffect(() => {
    let alive = true;
    const refresh = async () => {
      const remote = await loadData();
      if (!alive) return;
      if (remote) {
        setDataState(remote);
        setSyncState("ok");
      } else if (remote === null && dataRef.current.donations.length === 0) {
        // first run: seed storage so both devices share one record
        const ok = await saveData(dataRef.current);
        setSyncState(ok ? "ok" : "error");
      }
    };
    refresh();
    const id = setInterval(refresh, POLL_MS);
    return () => {
      alive = false;
      clearInterval(id);
    };
  }, []);
 
  if (!mode) return <Landing onPick={setMode} />;
  if (mode === "display")
    return <DisplayView data={data} onExit={() => setMode(null)} />;
  return (
    <ConsoleView
      data={data}
      setData={setData}
      onExit={() => setMode(null)}
      syncState={syncState}
    />
  );
}